# -*- coding: utf-8 -*-
"""АДП, последний добор 16.11.2026: постановления Пленума и обзоры Верховного Суда РФ, которых не было в базе.
Кладёт файлы в папки судебной практики, дописывает раздел А.11 реестра, раздел 2.2, справку по вопросам,
контрольные суммы и счётчики. Повторный запуск ничего не меняет: документ, уже лежащий в базе, пропускается."""
import os, re, shutil, hashlib, html
ROOT = os.path.abspath(os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', '..', '..'))
os.chdir(ROOT)
A = 'Административная деятельность полиции/2. Источники/'
W = '.work/adp/'; H = 'Исходные страницы (HTML)/'
PL = '2. Судебная практика/2. Пленум Верховного Суда РФ/'; OB = '2. Судебная практика/3. Обзоры и иные акты Верховного Суда РФ/'
# ключ, папка, имя файла, краткое обозначение, раздел справки, позиция (по прочитанному тексту; '' — позиции не выписаны)
ITEMS = [
 ('pl_20240625_20', PL, 'Постановление Пленума ВС РФ от 25.06.2024 № 20 (центр временного содержания несовершеннолетних, главы 31.2 и 31.3 КАС РФ)', 'Пленум ВС от 25.06.2024 № 20', '1.9',
  'Дела о помещении несовершеннолетнего в центр временного содержания органа внутренних дел и о продлении срока пребывания рассматриваются по главе 31.2 КАС и не могут рассматриваться в упрощённом (письменном) производстве (п. 2). Место задержания (ч. 1 ст. 285.6 КАС) — место выявления несовершеннолетнего либо оформления материалов сотрудником органа внутренних дел (п. 3). Орган внутренних дел подаёт административный иск в течение месяца со дня постановления о прекращении уголовного дела или об отказе в его возбуждении либо возникновения иного основания; заявление о восстановлении срока подаётся вместе с иском, без него иск возвращается (п. 4)'),
 ('pl_20201217_43', PL, 'Постановление Пленума ВС РФ от 17.12.2020 № 43 (статьи 324–327.1 УК РФ, официальные документы)', 'Пленум ВС от 17.12.2020 № 43', '1.14',
  'Официальный документ (ст. 324, ч. 1 ст. 325 УК) — документ, в том числе электронный, который создаётся, выдаётся или заверяется в установленном порядке органами власти либо уполномоченными организациями или лицами и удостоверяет юридически значимые факты (п. 1). Важные личные документы (ч. 2 ст. 325 УК) — помимо паспорта, вид на жительство, военный билет, водительское удостоверение, пенсионное удостоверение, свидетельство о регистрации транспортного средства и другие (п. 2)'),
 ('pl_20181225_46', PL, 'Постановление Пленума ВС РФ от 25.12.2018 № 46 (статьи 137–139, 144.1, 145, 145.1 УК РФ)', 'Пленум ВС от 25.12.2018 № 46', '1.1',
  'Ст. 139 УК: ответственность наступает за проникновение в жилище против воли проживающего при отсутствии оснований, предусмотренных УПК и другими федеральными законами, в частности ст. 15 ФЗ «О полиции» (п. 10). Жилище — также апартаменты, садовый дом; не жилище — сарай, баня, гараж, если они не приспособлены для проживания (п. 11). Отказ лица, вошедшего с согласия проживающего, покинуть жилище состава не образует (п. 13)'),
 ('pl_20181225_50', PL, 'Постановление Пленума ВС РФ от 25.12.2018 № 50 (оспаривание нормативных правовых актов)', 'Пленум ВС от 25.12.2018 № 50', '1.11', ''),
 ('pl_20240625_17', PL, 'Постановление Пленума ВС РФ от 25.06.2024 № 17 (административные правонарушения в сфере информационного обеспечения выборов)', 'Пленум ВС от 25.06.2024 № 17', '1.14', ''),
 ('obz_2025_3', OB, 'Обзор судебной практики ВС РФ № 3 (2025) (утв. Президиумом ВС РФ 08.10.2025)', 'Обзор ВС № 3 (2025)', '', ''),
 ('obz_2025_4', OB, 'Обзор судебной практики ВС РФ № 4 (2025) (утв. Президиумом ВС РФ 22.12.2025)', 'Обзор ВС № 4 (2025)', '', ''),
 ('obz_2026_1', OB, 'Обзор судебной практики ВС РФ № 1 (2026) (утв. Президиумом ВС РФ 25.03.2026)', 'Обзор ВС № 1 (2026)', '', ''),
 ('obz_2026_2', OB, 'Обзор судебной практики ВС РФ № 2 (2026) (утв. Президиумом ВС РФ 01.07.2026)', 'Обзор ВС № 2 (2026)', '', ''),
 ('obz_2026_3', OB, 'Обзор судебной практики ВС РФ № 3 (2026) (утв. Президиумом ВС РФ 14.10.2026)', 'Обзор ВС № 3 (2026)', '', ''),
]
import csv, glob
LOG = {}
for f in sorted(glob.glob('.github/downloader/logs/*.tsv')):
    for r in csv.reader(open(f, encoding='utf-8'), delimiter='\t'):
        if len(r) >= 5 and r[4] == 'ok': LOG[r[3]] = r[2]
def sha(p):
    h = hashlib.sha256(); h.update(open(p, 'rb').read()); return h.hexdigest()
new = []
for key, folder, name, short, sec, pos in ITEMS:
    src = W + key + '.pdf'; hs = W + H + key + '.html'
    assert len((name + '.html').encode()) <= 225, name
    if os.path.exists(A + folder + name + '.pdf') or not os.path.exists(src): continue
    page = open(hs, encoding='utf-8', errors='replace').read()
    assert 'Документ утратил силу или отменен' not in re.sub(r'<[^>]+>', ' ', page[:200000]), key
    title = ' '.join(html.unescape(re.search(r'<title>(.*?)</title>', page, re.S).group(1)).split(' \\ ')[0].split())
    url = LOG.get(src, '')
    assert url, key
    os.makedirs(A + folder + H, exist_ok=True)
    shutil.copyfile(src, A + folder + name + '.pdf'); shutil.copyfile(hs, A + folder + H + name + '.html')
    new.append(dict(key=key, folder=folder, name=name, short=short, sec=sec, pos=pos, title=title, url=url))
print('размещено:', len(new), [n['key'] for n in new])
if new:
    npl = sum(1 for n in new if n['folder'] == PL); nob = len(new) - npl
    # --- реестр
    rp = A + 'Реестр источников.md'; s = open(rp, encoding='utf-8').read()
    rows = ['| %s | %s.pdf | [consultant.ru](%s) | %s |' % (n['folder'].split('/')[1], n['name'], n['url'], n['title'].replace('|', '/')) for n in new]
    head = '### А.11. Добавлено 16.11.2026 (последний добор): судебная практика\n\n'
    if head not in s:
        block = (head + 'Постановления Пленума и обзоры Верховного Суда РФ, которые раньше значились в разделе 2.2 как не скачанные, и два постановления Пленума 2024 года, '
                 'найденные при просмотре перечня постановлений за 2023–2026 годы. Тексты — consultant.ru (не официальный источник); редакция — по заголовку документа на сайте; '
                 'на каждой сохранённой странице проверено, что отметки «Документ утратил силу или отменен» нет.\n\n| Папка | Файл | Откуда | Что в файле |\n|---|---|---|---|\n')
        s = s.replace('## Б. Перепроверка 14.11.2026', block + '\n'.join(rows) + '\n\n## Б. Перепроверка 14.11.2026', 1)
    else:
        i = s.find(head); j = s.find('\n\n## Б. Перепроверка', i); s = s[:j] + '\n' + '\n'.join(rows) + s[j:]
    open(rp, 'w', encoding='utf-8').write(s)
    # --- контрольные суммы
    cp = A + 'Контрольные суммы SHA-256.txt'
    L = [l for l in open(cp, encoding='utf-8').read().split('\n') if l]
    for n in new:
        for rel in (n['folder'] + n['name'] + '.pdf', n['folder'] + H + n['name'] + '.html'): L.append('%s  %s' % (sha(A + rel), rel))
    L.sort(key=lambda l: l.split('  ', 1)[1])
    open(cp, 'w', encoding='utf-8').write('\n'.join(L) + '\n')
    # --- справка по вопросам: позиции
    jp = A + '2. Судебная практика/Судебная практика по вопросам.md'; t = open(jp, encoding='utf-8').read()
    for n in new:
        if not n['sec'] or not n['pos']: continue
        m = re.search(r'^### %s\. .*?\n\n\|.*?\n\|[-|]+\n((?:\|.*\n)+)' % re.escape(n['sec']), t, re.M)
        t = t[:m.end(1)] + '| %s | %s |\n' % (n['short'], n['pos']) + t[m.end(1):]
    open(jp, 'w', encoding='utf-8').write(t)
